using Microsoft.IdentityModel.Tokens;using Shared;using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;
public record AuthDto(string Email,string Password,string? DisplayName);public record SaveAirlineDto(Guid AirlineId);public record AirlineDto(string Name,string IataCode,string Country,bool IsActive=true);public record NoteDto(string Content);
public class JwtTokenService(IConfiguration cfg){public string Create(User u){var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.DisplayName),new Claim(ClaimTypes.Email,u.Email),new Claim(ClaimTypes.Role,u.Role)};var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(cfg["JWT_SECRET"]??"development-secret-at-least-32-characters"));var jwt=new JwtSecurityToken(cfg["JWT_ISSUER"]??"AirlineIntelligence",cfg["JWT_AUDIENCE"]??"AirlineIntelligence.Web",claims,expires:DateTime.UtcNow.AddHours(12),signingCredentials:new(key,SecurityAlgorithms.HmacSha256));return new JwtSecurityTokenHandler().WriteToken(jwt);}}
public static class ApiView{public static object User(User u)=>new{u.Id,u.Email,u.DisplayName,u.Role,u.CreatedAt};public static object Airline(Airline a)=>new{a.Id,a.Name,a.IataCode,a.Country,a.IsActive,statistics=a.Statistics is null?null:new{a.Statistics.OverallScore,a.Statistics.AverageRating,a.Statistics.PositiveSentimentPercent,a.Statistics.StaffScore,a.Statistics.ServiceScore,a.Statistics.AveragePrice,a.Statistics.LowestPrice,a.Statistics.HighestPrice,a.Statistics.FlightsPerWeek,a.Statistics.DestinationCount,a.Statistics.RouteCount,a.Statistics.EnvironmentalScore,a.Statistics.AverageCo2,a.Statistics.PassengerExperienceScore,a.Statistics.PriceScore,a.Statistics.AvailabilityScore,a.Statistics.PositiveTopics,a.Statistics.Complaints}};public static Guid UserId(ClaimsPrincipal p)=>Guid.Parse(p.FindFirstValue(ClaimTypes.NameIdentifier)!);}
